// ---------- اختيار البرامج المرتبطة بسؤال الطالب (عشان الـ prompt ميتقلش) ----------

function normalize(s: string): string {
  return s
    .replace(/[\u064B-\u0652\u0640]/g, "")
    .replace(/[أإآ]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ة/g, "ه")
    .toLowerCase();
}

const has = (t: string, ...words: string[]) => words.every((w) => t.includes(w));
const hasAny = (t: string, ...words: string[]) => words.some((w) => t.includes(w));

export function pickProgramIds(userText: string): number[] {
  const t = normalize(userText);
  const ids: number[] = [];
  const add = (n: number) => {
    if (!ids.includes(n)) ids.push(n);
  };

  const chem = has(t, "كيمياء");
  const phys = has(t, "فيزياء");

  // مزدوجة أولاً (الأدق)
  if (phys && chem) add(16);
  if (has(t, "رياضيات") && phys) add(15);
  if (phys && hasAny(t, "الكترونيات", "الكترونيات")) add(14);
  if (chem && has(t, "جيولوجيا")) add(17);
  if (chem && has(t, "نبات")) add(18);
  if (chem && has(t, "ميكروبيولوجي")) add(19);
  if (chem && hasAny(t, "حيوان")) add(20);
  if (chem && has(t, "حشرات")) add(21);

  // منفردة
  if (has(t, "رياضيات")) add(1);
  if (hasAny(t, "احصاء", "احصائي")) add(2);
  if (hasAny(t, "حاسب", "كمبيوتر", "برمجه")) add(3);
  if (phys) add(4);
  if (chem) add(5);
  if (hasAny(t, "جيولوجيا") && !has(t, "بترول")) add(6);
  if (hasAny(t, "جيوفيزياء")) add(7);
  if (hasAny(t, "بترول")) add(8);
  if (has(t, "نبات") && !has(t, "بيوتكنولوجي")) add(9);
  if (hasAny(t, "ميكروبيولوجي", "ميكروب")) add(10);
  if (hasAny(t, "علم الحيوان", "حيوان")) add(11);
  if (has(t, "حشرات")) add(12);
  if (hasAny(t, "مصايد", "اسماك")) add(13);

  // أكواد المقررات (مثلاً 353ف أو 211ر)
  const codeLetter = /\b\d{3}\s?(را|رك|ر|ف|ك|ج|ح|ن|ز|ط|ص|ش|ها|هـ)(?![\u0621-\u064A])/g;
  let m: RegExpExecArray | null;
  const map: Record<string, number[]> = {
    ر: [1, 2, 3, 15],
    را: [2],
    رك: [3],
    ف: [4, 14, 15, 16],
    ك: [5, 16, 17, 18, 19, 20, 21],
    ج: [6, 7],
    ح: [11, 12, 13],
    ن: [9, 10],
  };
  while ((m = codeLetter.exec(t)) !== null) {
    (map[m[1]] || []).slice(0, 2).forEach(add);
  }

  return ids.slice(0, 4);
}

const COURSE_WORDS = ["متطلب", "مقرر", "كورس", "ماده", "مواد", "كود", "اجباري", "اختياري", "تخدم التخصص", "جدول", "خطه"];

export function buildSystemPrompt(userTexts: string[]): string {
  const recent = userTexts.slice(-3).join(" \n ");
  const ids = pickProgramIds(recent);
  const picked = PROGRAMS.filter((p) => ids.includes(p.id));

  let programsBlock: string;
  if (picked.length) {
    programsBlock =
      "############ مقررات البرامج المرتبطة بسؤال الطالب ############\n" +
      CODE_LEGEND +
      "\n\n" +
      picked.map((p) => p.text).join("\n\n");
  } else {
    const wantsCourses = COURSE_WORDS.some((w) => normalize(recent).includes(w));
    programsBlock =
      "############ فهرس برامج المقررات المتاحة عندي ############\n" +
      PROGRAMS.map((p) => p.id + ") " + p.name).join(" — ") +
      "\n" +
      (wantsCourses
        ? "ملاحظة: الطالب بيسأل عن مقررات ولسه ما حددش برنامجه. اسأله هو في أنهي برنامج وبعدها جاوب (تفاصيل كل برنامج بتظهر لما يذكره)."
        : "تفاصيل مقررات أي برنامج بتظهر لما الطالب يذكر اسم البرنامج أو كود مقرر منه.");
  }

  return [CORE_RULES, "## معلومات كلية العلوم — جامعة أسيوط:", CORE_INFO, COMMON_REQUIREMENTS, programsBlock].join("\n\n");
}
